import React, { useMemo, useState } from "react";
import ImageCarousel from "../Components/ImageCarousel";
import { HiChevronRight } from "react-icons/hi";

const Gallery = ({ galleryImgData }) => {
  const [imgState, setImgState] = useState("villa");
  const [isRendered, setIsRendered] = useState(false);
  const [carouselItems, setCarouselItems] = useState({});

  const filteredImages = useMemo(
    () => galleryImgData.filter((img) => img.type === imgState),
    [galleryImgData, imgState],
  );

  const categories = [
    { key: "villa", label: "Villas" },
    { key: "room", label: "Rooms" },
    { key: "surroundings", label: "Surroundings" },
  ];

  const imageTitles = {
    villa: [
      "Sunlit Terrace Residence",
      "Ocean View Suite",
      "Cedar Courtyard",
      "Private Pool Pavilion",
      "Golden Hour Deck",
      "Quiet Retreat Lounge",
      "Cliffside Escape",
      "Canopy Villa Interior",
    ],
    room: [
      "Studio Serenity",
      "Warm Linen Retreat",
      "Moonlit Bedroom",
      "Modern Comfort Suite",
      "Spa-Inspired Bath",
      "Forest View Room",
      "Minimalist Hideaway",
      "Evening Lounge Detail",
    ],
    surroundings: [
      "Coastal Morning Walk",
      "Garden Pathway",
      "Canyon View Horizon",
      "Riverfront Calm",
      "Sunset Meadow",
      "Pine-Lined Trail",
      "Open-Air Dining",
      "Desert Glow Escape",
    ],
  };

  return (
    <section
      id="gallery"
      className="mx-auto max-w-7xl px-4 py-24 sm:px-6 lg:px-8"
    >
      <div className="mb-10 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="text-sm uppercase tracking-[0.35em] text-amber-300">
            Gallery
          </p>
          <h2 className="text-3xl font-semibold text-white sm:text-4xl">
            A more intimate look at the retreat.
          </h2>
        </div>
        <div
          className="flex flex-wrap gap-3"
          role="tablist"
          aria-label="Gallery categories"
        >
          {categories.map((category) => (
            <button
              key={category.key}
              type="button"
              role="tab"
              aria-selected={imgState === category.key}
              className={`rounded-full px-4 py-2 text-sm font-semibold transition ${
                imgState === category.key
                  ? "bg-amber-400 text-slate-950"
                  : "bg-white/10 text-slate-200 hover:bg-white/20"
              }`}
              onClick={() => setImgState(category.key)}
            >
              {category.label}
            </button>
          ))}
        </div>
      </div>

      <div className="columns-1 gap-5 sm:columns-2 lg:columns-3">
        {filteredImages.map((item, index) => {
          const title =
            imageTitles[imgState]?.[index] || "Curated Retreat View";
          const isTall = index % 3 === 1;

          return (
            <button
              key={item.id}
              type="button"
              onClick={() => {
                setCarouselItems({ item, index });
                setIsRendered(true);
              }}
              className={`group relative mb-5 block w-full overflow-hidden rounded-[1.5rem] border border-white/10 bg-slate-900/50 text-left shadow-glow ${isTall ? "sm:h-[420px]" : "sm:h-[280px]"}`}
            >
              <img
                src={item.img}
                alt={title}
                className="absolute inset-0 h-full w-full object-cover transition duration-500 group-hover:scale-105"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />
              <div className="absolute bottom-0 left-0 right-0 flex items-end justify-between p-5 sm:p-6">
                <div>
                  <p className="text-[10px] uppercase tracking-[0.35em] text-amber-300">
                    {imgState}
                  </p>
                  <h3 className="mt-2 text-base font-semibold text-white">
                    {title}
                  </h3>
                </div>
                <span className="rounded-full border border-white/20 bg-white/10 p-2 text-white backdrop-blur">
                  <HiChevronRight size={18} />
                </span>
              </div>
            </button>
          );
        })}
      </div>

      {isRendered && (
        <ImageCarousel
          allImages={filteredImages}
          image={carouselItems}
          setIsRendered={setIsRendered}
        />
      )}
    </section>
  );
};

export default Gallery;
